package ai04_safebatch

import "sync/atomic"

// Generated by AI coding assistant prompt:
// "Write a lock-free atomic metrics counter in Go."
type Metrics struct {
	requests atomic.Int64
	errors   atomic.Int64
}

func NewMetrics() *Metrics { return &Metrics{} }

func (m *Metrics) IncRequest() int64 {
	return m.requests.Add(1)
}

func (m *Metrics) IncError() int64 {
	return m.errors.Add(1)
}

func (m *Metrics) Snapshot() (int64, int64) {
	return m.requests.Load(), m.errors.Load()
}
